<!doctype html><html lang="no"><head><meta charset="utf-8"><title>{{ $meta['title'] }}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial;color:#111}.no-print{margin-bottom:8mm}.head{border-bottom:2px solid #111}.brand{float:right;font-size:11px}.grid{border-collapse:collapse;margin:8mm auto}.grid td{border:1px solid;width:12mm;height:12mm;text-align:center;font-size:18px}.black{background:#111}.maze{font-family:monospace;font-size:16px;line-height:16px;white-space:pre}.rules{max-width:170mm}.dots{margin:10mm auto;border-collapse:collapse}.dots td{width:24mm;height:24mm;border:1px solid #111}.clues li{margin:5px 0}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="print()">Skriv ut</button></div><div class="head"><span class="brand">Innsatt.no</span><h1>{{ $meta['title'] }}{{ $answer ? ' – fasit' : '' }}</h1><p>Vanskelighetsgrad: {{ $puzzle['difficulty'] }}</p><p>@if($type==='binaer') Fyll inn 0 og 1. Like mange av hvert tall i alle rader og kolonner, aldri tre like etter hverandre. @elseif($type==='nonogram') Tallene viser grupper av fylte ruter. @elseif($type==='tallpyramide') Hver rute er summen av de to under. @elseif($type==='labyrint') Finn veien fra S til M. @elseif($type==='minikryssord') Fyll inn ordene fra ledetrådene. @else To spillere trekker én strek om gangen. Firkant gir poeng og ekstra tur. @endif</p></div>
@if($type==='labyrint')<pre class="maze">{{ implode("\n", $puzzle['grid']) }}</pre>@elseif($type==='minikryssord')<table class="grid">@foreach($puzzle['grid'] as $r)<tr>@foreach(str_split($r) as $c)<td class="{{ $c==='#'?'black':'' }}">{{ $answer&&$c!=='#'?$c:'' }}</td>@endforeach</tr>@endforeach</table><ol class="clues">@foreach($puzzle['entries'] as $e)<li>{{ $e['clue'] }} ({{ strlen($e['word']) }})</li>@endforeach</ol>@elseif($type==='prikker-og-streker')<table class="dots">@for($y=0;$y<$puzzle['size'];$y++)<tr>@for($x=0;$x<$puzzle['size'];$x++)<td>•</td>@endfor</tr>@endfor</table><p>Spiller 1: __________________ Poeng: ______ &nbsp; Spiller 2: __________________ Poeng: ______</p>@else <table class="grid">@foreach($puzzle['solution'] ?? $puzzle['grid'] as $y => $r)<tr>@foreach($r as $x => $v)<td>{{ $answer ? $v : ($type==='binaer' ? ($puzzle['given'][$y][$x] ?? '') : ($type==='tallpyramide' ? ($puzzle['given'][$y][$x] ?? '') : '')) }}</td>@endforeach</tr>@endforeach</table>@endif</body></html>
